# Find ORFs: ATG ... stop, all frames, both strands
import re
with open('region.fasta') as f:
    lines = f.read().splitlines()
seq = ''.join(lines[1:]).upper()

stopp = {'TAA','TAG','TGA'}
def orfs(s):
    found = []
    for strand, ss in [('+', s), ('-', rev := s.translate(str.maketrans('ACGT','TGCA'))[::-1])]:
        for frame in range(3):
            i = frame
            while i + 3 <= len(ss):
                if ss[i:i+3] == 'ATG':
                    j = i
                    while j + 3 <= len(ss):
                        if ss[j:j+3] in stopp:
                            found.append((strand, i, j+3, (j+3-i)//3))
                            break
                        j += 3
                i += 3
    return found

